CREATE TABLE IF NOT EXISTS telegram_config(id INTEGER PRIMARY KEY CHECK(id=1), body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS telegram_pairs(code TEXT PRIMARY KEY, expires INTEGER NOT NULL, body TEXT);
CREATE TABLE IF NOT EXISTS telegram_peers(chat INTEGER PRIMARY KEY, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS telegram_users(id INTEGER PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS telegram_jobs(id INTEGER PRIMARY KEY, chat INTEGER NOT NULL, user INTEGER NOT NULL, status TEXT NOT NULL, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS telegram_history(seq INTEGER PRIMARY KEY AUTOINCREMENT, chat INTEGER NOT NULL, user INTEGER NOT NULL, epoch INTEGER NOT NULL, role TEXT NOT NULL, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS telegram_context(chat INTEGER NOT NULL, user INTEGER NOT NULL, epoch INTEGER NOT NULL DEFAULT 0, summary TEXT NOT NULL DEFAULT '', through INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(chat,user));
CREATE TABLE IF NOT EXISTS telegram_outbox(id TEXT PRIMARY KEY, chat INTEGER NOT NULL, kind TEXT NOT NULL, reference TEXT, status TEXT NOT NULL, body TEXT NOT NULL, message_id INTEGER, expires INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS telegram_messages ON telegram_outbox(chat,message_id);
CREATE TABLE IF NOT EXISTS telegram_observer(id INTEGER PRIMARY KEY CHECK(id=1), hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS telegram_agent_runs(job INTEGER NOT NULL, phase TEXT NOT NULL, body TEXT NOT NULL, PRIMARY KEY(job,phase));
PRAGMA user_version=14;
